var builder = DistributedApplication.CreateBuilder(args);

// ---------------------------------------------------------------------------
// Infrastructure (Docker containers). Data volumes keep the data between runs.
// Passwords are generated by Aspire and stored in the AppHost user-secrets.
// ---------------------------------------------------------------------------

// Mongo: listening_events, city_models, upload/retrieve tasks, Spotify accounts
var mongo = builder.AddMongoDB("mongo")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent)
    .WithMongoExpress();
var cityfyDb = mongo.AddDatabase("cityfy");

// SQL Server: MusicBrainz genres/artists
var sql = builder.AddSqlServer("sql")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent);
var musicBrainzDb = sql.AddDatabase("musicbrainz");

// RabbitMQ: event bus of the pipeline (see ServiceDefault/Contracts/PipelineMessages.cs)
var broker = builder.AddRabbitMQ("broker")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent)
    .WithManagementPlugin();

// Secrets: set once in the AppHost user-secrets ("Parameters:spotify-client-secret")
// or when the dashboard asks for them.
var spotifyClientSecret = builder.AddParameter("spotify-client-secret", secret: true);

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------

var retrieveDumpSpotify = builder.AddProject<Projects.CityFy_Retrieve_Dump_Spotify>("RetrieveDumpSpotify")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker);

var retrieveSpotify = builder.AddProject<Projects.CityFy_Retrieve_Spotify>("RetrieveSpotify")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker)
    .WithEnvironment("Spotify__ClientSecret", spotifyClientSecret);

var retrieveMusicBrainz = builder.AddProject<Projects.CityFy_Retrieve_MusicBrainz>("RetrieveMusicBrainz")
    .WithHttpHealthCheck("/health")
    .WithReference(musicBrainzDb)
    .WaitFor(musicBrainzDb);

// Elaboration calls the MusicBrainz read API (artist resolve, genre graph) via service discovery
var elaboration = builder.AddProject<Projects.CityFy_Elaboration>("Elaboration")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(retrieveMusicBrainz)
    .WaitFor(retrieveMusicBrainz)
    .WithReference(broker)
    .WaitFor(broker);

// Orchestrator: ListeningImported -> (debounce) -> BuildCityRequested -> CityBuilt/CityBuildFailed
var orchestrator = builder.AddProject<Projects.CityFy_Orchestrator>("Orchestrator")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker);

// Public API: the only service meant to be reachable from browsers (session, /api/v1).
// Spotify redirects to its /api/v1/auth/callback (Spotify:RedirectUri of RetrieveSpotify).
var api = builder.AddProject<Projects.CityFy_Api>("Api")
    .WithHttpHealthCheck("/health")
    .WithReference(elaboration).WaitFor(elaboration)
    .WithReference(orchestrator).WaitFor(orchestrator)
    .WithReference(retrieveSpotify).WaitFor(retrieveSpotify)
    .WithReference(retrieveDumpSpotify).WaitFor(retrieveDumpSpotify);

// Frontend (Angular, cityfy-web): ng serve on http://127.0.0.1:4200 with a proxy /api -> Api.
// Browser, Spotify callback and session cookie all live on this single origin; the fixed
// loopback address is what the Spotify dashboard accepts as an http redirect URI.
builder.AddJavaScriptApp("Web", "../../cityfy-web", "start")
    .WithHttpEndpoint(port: 4200, isProxied: false)
    .WithExternalHttpEndpoints()
    .WithReference(api)
    .WaitFor(api);

builder.Build().Run();
